insert into public.routes (slug, name, name_en, region_id, difficulty, days_min, days_max, duration_hours, distance_km, elevation_gain_m, elevation_loss_m, max_altitude_m, min_altitude_m, route_type, season_months, tags, summary, description, difficulty_notes, getting_there, accommodation, water, permits, dangers, mobile_coverage, gear, tips, start_name, start_lat, start_lng, end_name, end_lat, end_lng, featured, status, sources) values
('mestia-ushguli','მესტია – უშგული','Mestia to Ushguli trek','svaneti','moderate',3,4,null,57,3300,2700,2700,1400,'one_way','{6,7,8,9,10}'::smallint[],array['villages','towers','glacier','pass','views','river_crossing','guesthouses']::text[],'საქართველოს ყველაზე ცნობილი მრავალდღიანი ლაშქრობა — ოთხი დღე სვანურ სოფლებს, კოშკებსა და მყინვარებს შორის, ყოველ ღამე საოჯახო სასტუმროში.','მარშრუტი ზემო სვანეთის ორ მთავარ პუნქტს აკავშირებს: მესტიას და უშგულს. ბილიკი გადის ძველ სოფლებზე — ჟაბეში, ადიში, ხალდე, იფრალი — სადაც ყოველ ღამე შეგიძლია საოჯახო სასტუმროში გაჩერდე, ამიტომ კარავი არ გჭირდება.

პირველი დღე მესტიიდან ტყიან ფერდობებზე ადის, უშბასა და თეთნულდზე ხედებით, და მულახის სოფლებში ჩადის. მეორე დღეს თეთნულდის სათხილამურო ზონის გავლით ადიშში მიდიხარ — ერთ-ერთ ყველაზე განმარტოებულ სვანურ სოფელში. მესამე დღე ყველაზე მძიმე და ყველაზე ლამაზია: ადიშის მყინვარის ძირში მდინარე ადიშისჭალა ხიდის გარეშე უნდა გადალახო (ფეხით ან ცხენით), შემდეგ ჩხუნდერის უღელტეხილზე (~2 700 მ) ადიხარ და ხალდეს ხეობაში ჩადიხარ. ბოლო დღე ენგურის ხეობას მიუყვება უშგულამდე — ევროპის ერთ-ერთ ყველაზე მაღალ მუდმივ დასახლებამდე, შხარის ფონზე.','ტექნიკური ადგილი არ არის, მაგრამ ოთხი სრული დღე, ჯამში ~3 300 მ აღმართი და მყინვარული მდინარის გადალახვა ნორმალურ ფიზიკურ ფორმას მოითხოვს.','მესტიამდე მარშრუტკები დადის თბილისიდან (~9 სთ), ქუთაისიდან და ბათუმიდან (~6 სთ) და ზუგდიდიდან (~3 სთ). უშგულიდან მესტიაში ტაქსით ან ჯიპით დაბრუნდები (~1.5 სთ; ფასი დამოკიდებულია მგზავრების რაოდენობაზე).','ყველა ღამე სოფლის საოჯახო სასტუმროში: ჟაბეში/ჩვაბიანი, ადიში, ხალდე ან იფრალი, უშგული. სეზონის პიკზე (ივლისი–აგვისტო) ადიშში წინასწარ დაჯავშნა ჯობს.','სასტუმროებში ონკანის წყალია. ბილიკზე ბევრი ნაკადულია, მაგრამ საძოვრების ქვემოთ წყალი გაწმინდე.','საშვი არ არის საჭირო.','ადიშისჭალას გადალახვა — ივლისის ბოლომდე და წვიმის შემდეგ წყალი ღრმა და ცივია; გადადი დილით ადრე ან ადგილობრივებს ცხენით გადაყვანა სთხოვე. ნისლსა და ჭექა-ქუხილში უღელტეხილზე ნუ ახვალ. შეიძლება შეგხვდეს მწყემსის ძაღლები.','სოფლებში ძირითადად არის, უღელტეხილებზე და ტყეში — ხშირად არა.',seed.gear(array['BOOTS','BACKPACK_MULTI','RAIN','FLEECE','HAT_GLOVES','SUN','WATER_2','FILTER','SNACKS','FIRST_AID','OFFLINE_MAP','POLES_REQ','HEADLAMP','POWERBANK','CASH','TRASH','SANDALS']),array['ადიშისჭალაზე გადასასვლელად გამოდი 7–8 საათზე — დღის მეორე ნახევარში მყინვარის დნობის გამო წყალი მატულობს.','ცხენით გადაყვანაზე ადიშში წინა საღამოს შეუთანხმდი სასტუმროს მასპინძელს.','თუ 3 დღეში გინდა, პირველი დღე ჟაბეშის ნაცვლად ადიშამდე ვერ გაჭიმავ — ჯობს მესამე და მეოთხე დღე გააერთიანო (ადიში – უშგული, ~29 კმ).','მესტიაში წინასწარ ჩამოტვირთე ოფლაინ რუკა: ბილიკი თეთრ-წითელი ნიშნებით არის მონიშნული, მაგრამ ზოგან ტყის გზები ერთმანეთს კვეთს.','ივნისის პირველ ნახევარში ჩხუნდერზე ჯერ კიდევ შეიძლება თოვლი იდოს — ჰკითხე ადგილობრივებს სანამ წახვალ.']::text[],'მესტია',43.04376,42.72445,'უშგული',42.91517,43.01148,true,'published','https://caucasus-trekking.com/best-treks ; https://transcaucasiantrail.org/wp-content/uploads/2018/01/Stage5_Adishi_Ushguli.pdf ; https://littleadventurertravels.com/destinations/europe/georgia/a-complete-guide-to-georgias-mestia-ushguli-hike/'),
('chalaadi-glacier','ჭალაადის მყინვარი','Chalaadi glacier','svaneti','easy',1,1,2.5,5.2,270,270,1925,1650,'out_and_back','{5,6,7,8,9,10,11}'::smallint[],array['glacier','forest','family','views']::text[],'ხეობის ტყეში გამავალი მოკლე და მარტივი ბილიკი მყინვარის ენამდე — მესტიიდან ყველაზე ადვილი გზა მყინვარის სანახავად.','მესტიიდან ჭალაადის ხიდამდე (~8 კმ) ტაქსით მიდიხარ — გზა მტვრიანია და ზაფხულში ჯიპები დადის. ხიდიდან ბილიკი ფიჭვნარ ტყეში მიუყვება მესტიაჭალას და თანდათან ადის მყინვარის მორენამდე, საიდანაც ჭალაადის მყინვარის ენა და მის ზემოთ მწვერვალები ჩანს. ბოლო მონაკვეთი ქვიან მორენაზე გადის.','მოკლე მანძილი და მცირე აღმართი. ბოლო ნაწილი ქვებზე გადის — ბავშვებთან ყურადღებით.','მესტიიდან ტაქსით ჭალაადის საკიდ ხიდამდე (~20 წთ). ფეხით მესტიიდან ცალ მხარეს ~11 კმ-ია, მტვრიან გზაზე.',null,'მდინარე გვერდით მიგყვება, მაგრამ მყინვარული წყალი ამღვრეულია — წყალი თან წაიღე.','არ არის საჭირო.','მყინვარის ენასთან ძალიან ახლოს ნუ მიხვალ და მის ქვეშ ნუ შეხვალ — ზემოდან ქვები და ყინული ცვივა.','ხეობაში სუსტია.',seed.gear(array['SHOES_LIGHT','WATER_1','SUN','RAIN','SNACKS','FIRST_AID','TRASH','FLEECE']),array['დილით წადი — შუადღისას ჯიპების გამო გზა მტვრიანია და ბილიკზე ხალხიც მეტია.','ტაქსის მძღოლს დაბრუნების დრო წინასწარ შეუთანხმე — ხიდთან კავშირი ცუდია.']::text[],'ჭალაადის საკიდი ხიდი',43.1075,42.736,'ჭალაადის მყინვარის მორენა',43.12069,42.72133,false,'published','https://caucasus-trekking.com/regions/svaneti/best-day-hikes-around-mestia ; https://transcaucasiantrail.org/en/day-hikes-from-mestia'),
('koruldi-lakes','კორულდის ტბები','Koruldi lakes','svaneti','moderate',1,1,6.5,13,1340,1340,2740,1450,'out_and_back','{6,7,8,9,10}'::smallint[],array['lakes','views','peak']::text[],'მესტიიდან ციცაბო, მაგრამ მარტივი ასვლა ალპურ ტბებამდე, საიდანაც უშბა და სვანეთის კავკასიონის მთელი კედელი ჩანს.','ბილიკი მესტიის ცენტრიდან იწყება და ჯერ ტყით ადის ჯვრამდე (~2 170 მ) — აქ ახალი სადამკვირვებლო მოედანია და ბევრი მხოლოდ აქამდე ადის. ჯვრიდან ფართო საძოვრებით ადიხარ კორულდის ტბებამდე (~2 740 მ). ტბები პატარაა, მაგრამ მათში უშბისა და ჩატინის ორწვერა სილუეტი ირეკლება. ძლიერი მოლაშქრეებისთვის შესაძლებელია ქედზე ასვლა ~3 300 მ-მდე.','~1 300 მ განუწყვეტელი აღმართი ერთ დღეში. თუ ჯვრამდე ჯიპით ახვალ, ლაშქრობა თითქმის მარტივი ხდება.','სტარტი მესტიის ცენტრიდანაა. ჯვრამდე/ტბებამდე ჯიპის ტაქსიც ადის (ფასი შეთანხმებით).',null,'ზედა ნაწილში წყარო თითქმის არ არის — წყალი მესტიიდან წაიღე.','არ არის საჭირო.','ზედა ნაწილი ღიაა — მზე და ქარი ძლიერია. ჭექა-ქუხილის დროს ქედზე ნუ დარჩები. ტბებში ცურვა არ არის რეკომენდებული.','უმეტესად არის — მესტია ახლოსაა.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH']),array['მზის ჩასვლა ტბებთან განსაკუთრებით ლამაზია, მაგრამ ჩამოსასვლელად ფანარი აუცილებლად წაიღე.','ივნისის დასაწყისში ზედა ფერდობებზე თოვლი შეიძლება ჯერ კიდევ იყოს.']::text[],'მესტია',43.04376,42.72445,'კორულდის ტბები',43.08675,42.70571,true,'published','https://transcaucasiantrail.org/en/day-hikes-from-mestia ; https://caucasus-trekking.com/regions/svaneti/best-day-hikes-around-mestia'),
('guli-pass-mazeri-mestia','მაზერი – გულის უღელტეხილი – მესტია','Mazeri to Mestia via Guli pass','svaneti','hard',1,2,9,22.6,1690,1460,2950,1450,'one_way','{7,8,9}'::smallint[],array['pass','views','glacier','camping']::text[],'ერთ-ერთი საუკეთესო დღიური ლაშქრობა საქართველოში: ბეჩოს ხეობიდან გულის უღელტეხილზე, უშბის ორი წვერის პირდაპირ ძირში, და მესტიაში ჩასვლა.','მაზერიდან (ბეჩოს თემი) ბილიკი ტყით ადის ფართო საძოვრებზე, შემდეგ კი ციცაბოდ — გულის უღელტეხილამდე (~2 950 მ). უღელტეხილიდან უშბა სულ ახლოსაა, ხოლო მეორე მხარეს მესტიის ხეობა და სვანეთის ქედი იშლება. ჩასვლა გრძელია და მუხლებს ტვირთავს. ორ დღედ გაყოფისას კარვით ღამე საძოვრებზე შეიძლება.','გრძელი დღე (~9 სთ), ~1 700 მ აღმართი და ~1 500 მ დაღმართი. ტექნიკური არ არის, მაგრამ უღელტეხილის ქვეშ ციცაბო ქვიანი ფერდობია.','მესტიიდან მაზერამდე ტაქსით (~45 წთ) — ჯობს დილით ადრე. ფინიში მესტიაშია, ასე რომ უკან ტრანსპორტი არ გჭირდება.','მაზერში რამდენიმე სასტუმროა — შეგიძლია წინა ღამე იქ გაატარო და ადრე გახვიდე.','ქვედა ნაწილში ნაკადულებია; უღელტეხილის ახლოს წყალი ცოტაა — 2 ლიტრი მაინც წაიღე.','არ არის საჭირო.','ამინდი უღელტეხილზე სწრაფად იცვლება. ივნისში და ოქტომბერში უღელტეხილის ქვეშ თოვლი შეიძლება იყოს. ნისლში ორიენტირება რთულია.','უღელტეხილზე ზოგჯერ არის, ხეობებში სუსტია.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH','HAT_GLOVES']),array['მიმართულება მაზერიდან მესტიისკენ ჯობს: ნაკლები აღმართია და ფინიშში ტრანსპორტი არ გჭირდება.','თუ გვიან დაიწყე, ჩასვლისთვის ფანარი აუცილებელია — დაღმართი 3–4 საათი გრძელდება.']::text[],'მაზერი',43.07384,42.61018,'მესტია',43.04376,42.72445,false,'published','https://www.caucasus-trekking.com/regions/svaneti/best-hikes-around-mazeri ; https://www.caucasus-trekking.com/best-hikes'),
('shdugra-waterfall','შდუგრას ჩანჩქერი','Shdugra waterfall (Mazeri)','svaneti','easy',1,1,5,14.8,520,520,2050,1550,'out_and_back','{5,6,7,8,9,10}'::smallint[],array['waterfall','forest','family','views']::text[],'დოლრას ხეობით მაღალ ჩანჩქერამდე, რომელიც უშბის მყინვარიდან ჩამოედინება — ბეჩოს ხეობის ყველაზე პოპულარული ლაშქრობა.','მაზერიდან ბილიკი მდინარე დოლრას ხეობას მიუყვება, ტყეებსა და მდელოებზე, სანამ არ მიადგები შდუგრას ჩანჩქერს, რომელიც ფართო კლდიდან ცვივა. ძლიერი მოლაშქრეები ხშირად აგრძელებენ უშბის მყინვარამდე (~3 400 მ), მაგრამ ეს უკვე რთული და გრძელი მარშრუტია და სასაზღვრო პოსტზე პასპორტს გთხოვენ.','ზომიერი აღმართი და კარგად გაკვალული ბილიკი. მთელ დღეს მოითხოვს, მაგრამ ტექნიკური არაფერია.','მესტიიდან მაზერამდე ტაქსით (~45 წთ).',null,'ბილიკზე რამდენიმე ნაკადულია.','ჩანჩქერამდე არ არის საჭირო. უშბის მყინვარისკენ გაგრძელებისას პასპორტი წაიღე.','ჩანჩქერთან ქვები სველი და მოლიპულია.','ხეობაში სუსტია.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH']),array['ფოტოსთვის საუკეთესო შუქი დილით არის — შუადღიდან ჩანჩქერი ჩრდილშია.']::text[],'მაზერი',43.07384,42.61018,'შდუგრას ჩანჩქერი',43.12981,42.6002,false,'published','https://www.caucasus-trekking.com/regions/svaneti/best-hikes-around-mazeri'),
('shkhara-glacier','შხარის მყინვარი უშგულიდან','Shkhara glacier from Ushguli','svaneti','easy',1,1,5,16,510,510,2550,2100,'out_and_back','{5,6,7,8,9,10}'::smallint[],array['glacier','views','family']::text[],'ფართო, თითქმის ბრტყელი ხეობით ენგურის სათავეებამდე — საქართველოს უმაღლესი მწვერვალის, შხარის კედლის ძირში.','უშგულიდან ბილიკი და ჯიპის გზა ენგურის ხეობას მიუყვება შხარის მყინვარის ენამდე. მარშრუტი ძალიან მარტივია, მაგრამ გრძელი, და მთელი გზა ხედი შხარაზე (5 193 მ) იშლება. ბილიკზე პატარა კაფეც არის.','თითქმის ბრტყელი, მაგრამ 16 კმ — სიმაღლეზე (2 100–2 500 მ) სიარული ჩვეულებრივზე უფრო ღლის.','უშგულში მესტიიდან ჯიპით (~1.5 სთ). მყინვარამდე ჯიპის ქირაობაც შეიძლება.',null,'ბილიკზე ნაკადულებია; მყინვარული წყალი ამღვრეულია.','არ არის საჭირო.','მყინვარის ენაზე ნუ ახვალ და მის ქვეშ ნუ დადგები. უშგულში სიმაღლე ~2 100 მ-ია — პირველ დღეს ნელა იარე.','სუსტი.',seed.gear(array['SHOES_LIGHT','WATER_1','SUN','RAIN','SNACKS','FIRST_AID','TRASH','FLEECE','BOOTS']),array['ზაფხულშიც უშგულში საღამოები ცივია — თბილი ფენა წაიღე.']::text[],'უშგული (ჩაჟაში)',42.91517,43.01148,'შხარის მყინვარის ენა',42.964,43.086,false,'published','https://www.caucasus-trekking.com/regions/svaneti/best-hikes-in-ushguli')
